        def _post_trust_credential_status_sync(self, tenant: str) -> None:
            # 外部凭证状态同步。请求/字段非法由 _read_json 与 store 抛
            # ValidationError -> 400；同 updated_at 不同内容由 store 抛
            # ConflictError -> 409。锚点缺失/吊销、签名格式错误、验签
            # 失败均按公开错误协议返回 200 + {"valid":false,"reason":...}
            # （前缀依次为“锚点”/“签名格式错误”/“签名校验失败”）且不写入。
            data = self._read_json()
            result = store.sync_credential_status(tenant, data)
            if not result.get("valid"):
                self._send_invalid(result.get("reason") or "验签失败")
                return
            record = result["record"]
            # 首次同步 201；严格更新或重放 200（重放内容不变）。
            self._send_json(
                result["status_code"],
                {
                    "issuer_did": record.issuer_did,
                    "credential_id": record.credential_id,
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                    "issuer_key_version": record.issuer_key_version,
                },
            )

        def _post_trust_credential_status_sync_batch(
            self, tenant: str
        ) -> None:
            # 批量外部凭证状态同步：任何失败都返回 HTTP 200。请求体须恰为
            # {"items": [项...]}，数组非空且不超过 100 项；请求体非法
            # （外层缺失、非法 JSON、非对象、字段缺失或多余、items 非数组、
            # 空数组或超过上限）时返回 {"results": [], "reason": "请求..."}。
            # 请求级合法时返回 {"results": [...]}，长度与顺序与输入一致，
            # 逐项复用单项同步规则，失败不短路：字段错误 400、同秒冲突
            # 409、锚点/签名失败 200 均收敛为单项结果（含 http_status 与
            # 非空中文 reason），不影响其余项；成功项首次 201，重放/更早
            # 日 200，严格更新 200 并记审计。显式空 X-Tenant-ID 在此之前
            # 由路由统一判 400；本地（本租户）凭证状态始终不变。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_json(
                    200,
                    {"results": [],
                     "reason": "请求不合法: 请求体缺失或长度声明非法"},
                )
                return
            except Exception:  # noqa: BLE001
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
                )
                return
            if not raw:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体缺失"}
                )
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_json(
                    200,
                    {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
                )
                return
            except json.JSONDecodeError:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
                )
                return

            try:
                ok, reason, results = store.sync_credential_status_batch(
                    tenant, data
                )
            except Exception:  # noqa: BLE001 批量同步失败绝不暴露内部细节
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 同步过程发生内部错误"}
                )
                return
            if not ok:
                self._send_json(
                    200, {"results": [], "reason": reason or "请求不合法"}
                )
                return
            self._send_json(200, {"results": results})

        def _get_trust_credential_status(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
            # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
            # 探测。已同步仅返回 status、reason、updated_at。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_synced_credential_status(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                },
            )

        def _get_trust_imported_credential(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET /v1/trust/credentials/imported/{credential_id}
            # ?issuer_did=...：issuer_did 须唯一且非空，缺失/重复/空值
            # 一律 400；未导入、跨租户或 issuer_did 不匹配（含他租户
            # 双键）404，存在性不可探测。成功 200 返回键序
            # issuer_did,credential_id,body,signature。纯只读，不写状态、
            # 不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_imported_credential(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "issuer_did": record.issuer_did,
                    "credential_id": record.credential_id,
                    "body": record.body,
                    "signature": record.signature,
                },
            )

        def _get_trust_credential_status_history(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}/history?issuer_did=...&limit=&after=
            # issuer_did 须唯一且非空，否则 400；limit 缺省 50，须为
            # 1..200 的 ASCII 十进制整数；after 缺省 0，须为非负 ASCII
            # 十进制整数；重复/非法一律 400。未同步双键（含他租户）404。
            # 只读：不写任何状态、不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)

            issuer_values = params.get("issuer_did")
            if issuer_values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(issuer_values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = issuer_values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )

            limit_values = params.get("limit")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            after_values = params.get("after")
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_synced_credential_status_history(
                tenant, issuer_did, credential_id, after, limit
            )
            self._send_json(
                200,
                {
                    "issuer_did": issuer_did,
                    "credential_id": credential_id,
                    "events": [
                        {
                            "status": event.status,
                            "reason": event.reason,
                            "updated_at": event.updated_at,
                            "issuer_key_version": event.issuer_key_version,
                            "audit_seq": event.audit_seq,
                            "audit_timestamp": event.audit_timestamp,
                            "cursor": event.cursor,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        def _get_audit(self, tenant: str, query: str) -> None:            # GET /v1/audit?limit=&after=：租户内按 seq 升序。
            # limit 缺省 50，须为 1..200 的整数；after 缺省 0，须为
            # 非负整数；非法一律 400。返回 events 与 next_after，
            # 空页 next_after 保持 after。
            params = parse_qs(query, keep_blank_values=True)
            limit_values = params.get("limit")
            after_values = params.get("after")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError("查询参数 limit 须在 1 到 200 之间")
            else:
                limit = 50
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_audit(tenant, after, limit)
            self._send_json(
                200,
                {
                    "events": [
                        {
                            "seq": event.seq,
                            "timestamp": event.timestamp,
                            "tenant_id": event.tenant_id,
                            "action": event.action,
                            "resource_type": event.resource_type,
                            "resource_id": event.resource_id,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

    return Handler


class _ReadyServer(ThreadingHTTPServer):
    """确定性端口生命周期的 HTTP 服务。

    - allow_reuse_address：退出后同端口立即可再次绑定；
    - daemon_threads：活动请求线程不阻塞进程退出；
    - 绑定失败时关闭已创建的监听套接字，不残留监听。
    """

    allow_reuse_address = True
    daemon_threads = True

    def server_bind(self) -> None:
        try:
            super().server_bind()
        except OSError:
            try:
                self.socket.close()
            except OSError:
                pass
            raise


def _oserror_chinese(what: str, exc: OSError) -> str:
    """把 OSError 映射为单行中文原因。"""
    code = getattr(exc, "errno", None)
    if code is not None:
        if code == errno.EADDRINUSE:
            return f"{what}地址已被占用"
        if code == errno.EACCES:
            return f"{what}权限不足"
        return f"{what}失败（错误码 {code}）"
    return f"{what}失败"


def run(
    host: str = "127.0.0.1",
    port: int = 8080,
    store_path: Optional[str] = None,
    quiet: bool = False,
) -> None:
    """启动 HTTP 服务（阻塞至 Ctrl-C 后返回 None）。

    参数非法抛 ValueError；绑定或状态文件 I/O 失败抛 OSError；状态
    JSON 不可解析抛 ValueError。任何失败路径都不输出 READY 行且不
    残留监听套接字。绑定成功后向 stdout 输出一行：
    ``VCBACKEND_READY host=<host> port=<实际端口>``（port=0 时报告
    内核分配的实际端口），UTF-8 编码并 flush。
    """
    # ---- 参数校验（先于任何副作用） -------------------------------- #
    if not isinstance(host, str) or not host:
        raise ValueError("host 必须为非空字符串")
    if isinstance(port, bool) or not isinstance(port, int):
        raise ValueError("port 必须为整数")
    if not 0 <= port <= 65535:
        raise ValueError("port 必须在 0 到 65535 之间")
    if store_path is not None and not isinstance(store_path, str):
        raise ValueError("store_path 必须为 None 或字符串")

    # ---- 加载状态文件（先绑定，失败时尚无监听套接字） -------------- #
    try:
        store = VCStore(store_path)
    except (ValueError, TypeError, AttributeError) as exc:
        # json.JSONDecodeError 本身是 ValueError 子类；损坏的字段值
        # （int() 失败等）与结构畸形（顶层非对象）同样归为状态不可解析。
        message = str(exc).strip() or "状态文件内容无法解析"
        message = message.replace("\r", " ").replace("\n", " ").strip()
        raise ValueError(f"状态文件不是合法 JSON：{message}") from exc
    except OSError as exc:
        raise OSError(
            f"状态文件读取失败：{_oserror_chinese('读取状态文件', exc)}"
        ) from exc

    handler = build_handler(store)
    if quiet:
        handler.log_message = lambda *args, **kwargs: None  # noqa: E731

    # ---- 绑定监听端口 ---------------------------------------------- #
    try:
        httpd = _ReadyServer((host, port), handler)
    except OSError as exc:
        raise OSError(
            f"监听地址绑定失败：{_oserror_chinese('绑定监听地址', exc)}"
        ) from exc

    actual_port = int(httpd.server_address[1])
    try:
        sys.stdout.buffer.write(
            f"VCBACKEND_READY host={host} port={actual_port}\n".encode("utf-8")
        )
        sys.stdout.buffer.flush()
    except (AttributeError, OSError):
        # 极端环境下 stdout 无 buffer（如测试替身）：退回文本接口。
        print(f"VCBACKEND_READY host={host} port={actual_port}", flush=True)

    # ---- 服务至 Ctrl-C：守护线程承担活动请求，不阻塞退出 ----------- #
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        return None
    finally:
        try:
            httpd.server_close()
        except OSError:
            pass
    return None

def sync_credential_status(
    self,
    tenant_id: str,
    data: Any,
) -> Dict[str, Any]:
    """同步一条外部凭证状态，返回结果字典。

    请求体须恰含 body（JSON 对象）与 signature（非空字符串）；
    body 须恰含 issuer_did、credential_id、status、updated_at、
    issuer_key_version，并可选 reason：
      - issuer_did/credential_id/status/updated_at 为非空字符串；
      - status 仅 active、revoked、unknown；
      - issuer_key_version 为非布尔正整数；
      - updated_at 为 UTC 秒精度 Z 格式（YYYY-MM-DDTHH:MM:SSZ）；
      - reason 提供时须为非空字符串。
    任何请求/字段非法均抛 ValidationError（HTTP 400）。

    签名覆盖 body 的规范化 JSON，用本租户 (issuer_did,
    issuer_key_version) 的 active 信任锚点公钥验签。锚点缺失/吊销、
    签名格式错误、密码学验签失败均不抛异常、不写入、不记审计，返回
    {"valid": False, "reason": ...}（reason 前缀依次为
    “锚点”/“签名格式错误”/“签名校验失败”）。

    验签通过后按 (issuer_did, credential_id) 双键在本租户内持久化：
      - 首次同步 201；
      - 相同内容（同 updated_at 且 status/version/reason 相同）重放
        200，不替换、不重复审计；
      - updated_at 严格更新才替换（200 并记审计）；更早或相等内容
        时间但内容不同的处理见下；
      - 同 updated_at 但内容不同抛 ConflictError（409），不写入。
    成功变更（首次或严格更新）记 trust.credential.status.synced，
    resource_id 为 issuer_did#credential_id；状态与审计同一次原子写，
    失败回滚。绝不改动本租户既有凭证状态。
    """
    # ---- 请求结构（错误 -> 400）----
    if not isinstance(data, dict):
        raise ValidationError("请求体必须为 JSON 对象")
    if set(data) != {"body", "signature"}:
        missing = [f for f in ("body", "signature") if f not in data]
        if missing:
            raise ValidationError(f"缺少字段: {', '.join(missing)}")
        extra = sorted(set(data) - {"body", "signature"})
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    body = data["body"]
    signature = data["signature"]
    if not isinstance(body, dict):
        raise ValidationError("字段 body 必须为 JSON 对象")
    if not isinstance(signature, str) or not signature:
        raise ValidationError("字段 signature 必须为非空字符串")

    # ---- body 字段（错误 -> 400）----
    required = (
        "issuer_did",
        "credential_id",
        "status",
        "updated_at",
        "issuer_key_version",
    )
    for field in required:
        if field not in body:
            raise ValidationError(f"body 缺少字段: {field}")
    extra = sorted(set(body) - set(required) - {"reason"})
    if extra:
        raise ValidationError(f"body 含多余字段: {', '.join(extra)}")
    issuer_did = body["issuer_did"]
    credential_id = body["credential_id"]
    status = body["status"]
    updated_at = body["updated_at"]
    key_version = body["issuer_key_version"]
    for name, value in (
        ("issuer_did", issuer_did),
        ("credential_id", credential_id),
        ("status", status),
        ("updated_at", updated_at),
    ):
        if not isinstance(value, str) or not value:
            raise ValidationError(
                f"body 字段 {name} 必须为非空字符串"
            )
    if status not in ("active", "revoked", "unknown"):
        raise ValidationError(
            "body 字段 status 仅支持 active、revoked、unknown"
        )
    if not isinstance(key_version, int) or isinstance(
        key_version, bool
    ) or key_version < 1:
        raise ValidationError(
            "body 字段 issuer_key_version 必须为非布尔正整数"
        )
    try:
        incoming_dt = _parse_utc_z(updated_at)
    except (TypeError, ValueError):
        raise ValidationError(
            "body 字段 updated_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    reason: Optional[str] = None
    if "reason" in body:
        reason = body["reason"]
        if not isinstance(reason, str) or not reason:
            raise ValidationError("body 字段 reason 必须为非空字符串")

    # ---- 锚点（缺失/吊销 -> 200 valid:false，且不写入）----
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None
            else None
        )
        anchor_row = (
            anchors.get(str(key_version))
            if anchors is not None
            else None
        )
        public_pem = (
            anchor_row.get("public_key", "")
            if anchor_row is not None
            else ""
        )
        anchor_status = (
            anchor_row.get("status", "active")
            if anchor_row is not None
            else None
        )
        anchor_uses = (
            anchor_row.get("uses")
            if anchor_row is not None
            else None
        )
    if anchor_row is None:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    if anchor_status == "revoked":
        return {
            "valid": False,
            "reason": f"锚点已吊销: {issuer_did}#{key_version}",
        }
    # 用途白名单：active 锚点无 status 用途时按锚点不可用处理
    if anchor_uses is not None and "status" not in anchor_uses:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return {
            "valid": False,
            "reason": (
                f"锚点公钥不可用: {issuer_did}#{key_version}"
                " 不是合法 P-256 公钥"
            ),
        }

    # ---- 签名（覆盖 body 的规范化 JSON）----
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return {
            "valid": False,
            "reason": "签名格式错误: 不是合法的 ES256 签名编码",
        }
    except crypto.InvalidSignature:
        return {
            "valid": False,
            "reason": "签名校验失败，状态正文或签名可能被改动",
        }
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return {"valid": False, "reason": "签名校验失败: 验签过程发生内部错误"}

    # ---- 持久化（双键隔离、严格更新、重放幂等、原子审计）----
    with self._lock:
        bucket = self._ensure_bucket_locked(tenant_id)
        sync_map = bucket.setdefault("credential_status_sync", {})
        issuer_map = sync_map.setdefault(issuer_did, {})
        existing = issuer_map.get(credential_id)
        if existing is not None:
            existing_dt = _parse_utc_z(existing["updated_at"])
            if incoming_dt == existing_dt:
                identical = (
                    existing.get("status") == status
                    and int(existing.get("issuer_key_version"))
                    == key_version
                    and existing.get("reason") == reason
                )
                if identical:
                    # 相同重放：200、不替换、不重复审计
                    return {
                        "valid": True,
                        "status_code": 200,
                        "record": self._sync_status_record(
                            issuer_did, credential_id, existing
                        ),
                    }
                # 同时间不同内容：冲突，不写入、不记审计
                raise ConflictError(
                    "凭证状态 updated_at 相同但内容不同: "
                    f"{issuer_did}#{credential_id}@{updated_at}"
                )
            if incoming_dt < existing_dt:
                # 更早的状态：忽略，保持既有值，200 且不记审计
                return {
                    "valid": True,
                    "status_code": 200,
                    "record": self._sync_status_record(
                        issuer_did, credential_id, existing
                    ),
                }

        # 首次同步（201）或严格更新（200）：替换状态、记审计、追加
        # 历史，三者在同一次原子写落盘（失败一并回滚）。重放、更早
        # 日期、同时间冲突均在上方提前返回，不会追加历史。
        created = existing is None
        new_row = {
            "status": status,
            "updated_at": updated_at,
            "issuer_key_version": key_version,
            "reason": reason,
        }
        snapshot = self._snapshot_locked()
        try:
            issuer_map[credential_id] = new_row
            event = self._append_audit_locked(
                tenant_id,
                AUDIT_TRUST_CREDENTIAL_STATUS_SYNCED,
                "trust_credential_status",
                f"{issuer_did}#{credential_id}",
            )
            entries = self._history_entries_locked(
                bucket, issuer_did, credential_id
            )
            entries.append(
                {
                    "status": status,
                    "reason": reason,
                    "updated_at": updated_at,
                    "issuer_key_version": key_version,
                    "cursor": self._next_history_cursor_locked(),
                    "audit_seq": int(event["seq"]),
                    "audit_timestamp": int(event["timestamp"]),
                }
            )
            self._save_locked()
        except Exception:
            self._restore_locked(snapshot)
            raise
        return {
            "valid": True,
            "status_code": 201 if created else 200,
            "record": self._sync_status_record(
                issuer_did, credential_id, new_row
            ),
        }

def sync_credential_status_batch(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """批量同步外部凭证状态，返回 (请求是否合法, 请求级原因, 逐项结果)。

    请求体须恰为 ``{"items": [项...]}``：数组非空且不超过 100 项。
    请求级结构不合法（非对象、字段缺失或多余、items 非数组、空数组或
    超过上限）时返回 ``(False, "请求...", [])``，由调用方回
    ``{"results": [], "reason": ...}``；请求级非法不写任何状态。

    请求级合法时逐项复用 :meth:`sync_credential_status` 的完整单项
    规则（body 字段、锚点、签名、双键严格更新/重放/冲突与原子落盘），
    按输入顺序收集结果，**失败不短路**：某项的字段错误、锚点/签名
    失败或同秒冲突均不影响其余项。每项失败结果键序为
    ``valid,http_status,reason``（字段错误 400、同秒冲突 409、锚点/
    签名失败 200，reason 恒为非空中文）；成功结果键序为
    ``valid,http_status,issuer_did,credential_id,status,reason,
    updated_at,issuer_key_version``（首次 201，重放/更早日 200，
    严格更新 200 并记审计）。每个成功项沿用单项的状态/历史/审计
    同次原子写，落盘失败回滚该项，跨重启保持。results 与输入等长、
    同序。
    """
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象", []
    if set(data) != {"items"}:
        if "items" not in data:
            return False, "请求缺少字段: items", []
        extra = sorted(set(data) - {"items"})
        return False, f"请求含多余字段: {', '.join(extra)}", []
    items = data["items"]
    if not isinstance(items, list):
        return False, "请求不合法: 字段 items 必须为数组", []
    if not items:
        return False, "请求不合法: items 数组不能为空", []
    if len(items) > 100:
        return False, (
            f"请求不合法: items 数组不能超过 100 项（当前 {len(items)} 项）"
        ), []

    results: List[Dict[str, Any]] = []
    for item in items:  # 顺序处理，失败不短路
        try:
            result = self.sync_credential_status(tenant_id, item)
        except ValidationError as exc:
            results.append(
                {"valid": False, "http_status": 400, "reason": str(exc)}
            )
            continue
        except ConflictError as exc:
            results.append(
                {"valid": False, "http_status": 409, "reason": str(exc)}
            )
            continue
        if not result.get("valid"):
            results.append(
                {
                    "valid": False,
                    "http_status": 200,
                    "reason": result.get("reason") or "验签失败",
                }
            )
            continue
        record = result["record"]
        results.append(
            {
                "valid": True,
                "http_status": result["status_code"],
                "issuer_did": record.issuer_did,
                "credential_id": record.credential_id,
                "status": record.status,
                "reason": record.reason,
                "updated_at": record.updated_at,
                "issuer_key_version": record.issuer_key_version,
            }
        )
    return True, "", results

def get_synced_credential_status(
    self, tenant_id: str, issuer_did: str, credential_id: str
) -> CredentialStatusSyncRecord:
    """查询已同步的外部凭证状态。

    按本租户 (issuer_did, credential_id) 双键查找；未同步或属他租户
    均抛 NotFoundError（HTTP 404，跨租户不可探测）。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
        if row is None:
            raise NotFoundError(
                "外部凭证状态未同步: "
                f"{issuer_did}#{credential_id}"
            )
        return self._sync_status_record(issuer_did, credential_id, row)

def list_synced_credential_status_history(
    self,
    tenant_id: str,
    issuer_did: str,
    credential_id: str,
    after: int = 0,
    limit: int = 50,
) -> Tuple[List[CredentialStatusHistoryEvent], int]:
    """查询某双键外部凭证的状态历史（只读），按页返回。

    - 双键在本租户未同步（含他租户）抛 NotFoundError（HTTP 404）；
    - 历史按 updated_at 升序、同 updated_at 按 cursor 升序排列；
    - 排除 cursor 不大于 after 的项，至多返回 limit 项；
    - next_after 为本页末项 cursor，空页保持 after。

    audit_seq 为 None 的兼容项（旧状态补录，无法追溯同步事件）
    仍照常按 cursor 返回。
    """
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        current_row = None
        entries: List[Dict[str, Any]] = []
        if bucket is not None:
            current_row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
            entries = list(
                bucket.get("credential_status_history", {})
                .get(issuer_did, {})
                .get(credential_id, [])
            )
        if current_row is None:
            raise NotFoundError(
                "外部凭证状态未同步: "
                f"{issuer_did}#{credential_id}"
            )

        def sort_key(row: Dict[str, Any]) -> Tuple[datetime, int]:
            return (
                _parse_utc_z(row["updated_at"]),
                int(row["cursor"]),
            )

        ordered = sorted(entries, key=sort_key)
        picked: List[CredentialStatusHistoryEvent] = []
        for row in ordered:
            if len(picked) >= limit:
                break
            cursor = int(row["cursor"])
            if cursor <= after:
                continue
            picked.append(
                CredentialStatusHistoryEvent(
                    status=row["status"],
                    reason=row.get("reason"),
                    updated_at=row["updated_at"],
                    issuer_key_version=int(row["issuer_key_version"]),
                    cursor=cursor,
                    audit_seq=(
                        int(row["audit_seq"])
                        if row.get("audit_seq") is not None
                        else None
                    ),
                    audit_timestamp=(
                        int(row["audit_timestamp"])
                        if row.get("audit_timestamp") is not None
                        else None
                    ),
                )
            )
        next_after = picked[-1].cursor if picked else after
        return picked, next_after

