        if extra:
            raise ValidationError(
                f"多余字段: {', '.join(extra)}"
            )
        if "reason" not in data:
            raise ValidationError("缺少字段: reason")
        reason = data["reason"]
        if not isinstance(reason, str):
            raise ValidationError("字段 reason 必须为字符串")
